import numpy as np

def annihilating_poly(A, v):
    A = np.array(A, dtype=float)
    K = [np.array(v, dtype=float)]
    while True:
        nxt = A @ K[-1]
        if np.linalg.matrix_rank(np.column_stack(K + [nxt])) == len(K):
            break
        K.append(nxt)
    c = np.linalg.lstsq(np.column_stack(K), nxt, rcond=None)[0]
    coeffs = [1.0] + [-x for x in c[::-1]]
    return (np.round(coeffs, 6) + 0.0).tolist()
